import { getTranslations, translate, Language } from '@/lib/translations';
import companyData from '@/content/company.json';

interface AboutProps {
  params: Promise<{ lang: Language }>;
}

export default async function About({ params }: AboutProps) {
  const { lang } = await params;
  const translations = getTranslations(lang);
  const t = (key: string, params?: Record<string, string>) => 
    translate(translations, key, params);

  return (
    <main className="container mx-auto px-4 py-12">
      <div className="max-w-4xl mx-auto">
        <h1 className="text-4xl font-bold text-gray-900 mb-6">{t('about.title')}</h1>
        <div className="prose prose-lg max-w-none">
          <p className="text-lg text-gray-700 mb-4">
            {t('about.description1', { companyName: companyData.name, location: companyData.location })}
          </p>
          <p className="text-lg text-gray-700 mb-4">
            {t('about.description2')}
          </p>
          <p className="text-lg text-gray-700">
            {t('about.description3')}
          </p>
        </div>
      </div>
    </main>
  );
}

